report['reference_bindings']={'exact_references':set(refs)=={x['reference_id'] for x in bindings['bindings']},'metadata_matches':all(all(refs[x['reference_id']].get(k)==x.get(k) for k in ('url','source_version','source_sha256')) for x in bindings['bindings'])}
replays=[]
for key in sorted(ce.keys()-be.keys()):
    edge_id=next(e for e in expected_edges if '_'+e+'_' in key)
    expected=expected_edges[edge_id]; actual=ce[key]
    qualifiers=expected.get('endpoint_qualifiers',[])
    citations=sorted({e['reference_id'] for e in expected['evidence']+sum((q['evidence'] for q in qualifiers),[])})
    checks={'subject':actual['subject']==expected['subject'],'object':actual['object']==expected['object'],'predicate':actual['predicate']==LOCAL_PREDICATE_CURIES[expected['predicate']],'description':actual['description']==expected.get('description',''),'evidence':json.loads(actual['evidence'])==expected['evidence'],'qualifiers':json.loads(actual['endpoint_qualifiers'] or '[]')==qualifiers,'references':json.loads(actual['reference_metadata'])==[refs[c] for c in citations],'source_records':actual['source_records']=='|'.join(citations)}
    replays.append({'edge':edge_id,'checks':checks})
missing_contexts=[]
for k,node in bn.items():
    for context in json.loads(node['source_contexts']):
        if context not in json.loads(cn.get(k,{}).get('source_contexts','[]')): missing_contexts.append([k,context])
node_checks=[]
