        checks={'context_complete':context in json.loads(actual['source_contexts']),'protein_category':n.get('category')!='protein' or actual['category']=='biolink:Protein','reaction_direction':collection!='reactions' or actual['direction']==n.get('direction','')}
        node_checks.append({'node':n['id'],'checks':checks})
report['kgx']={'baseline_edges':len(be),'current_edges':len(ce),'added_edges':len(replays),'removed_edges':sorted(be.keys()-ce.keys()),'changed_prior_edges':[k for k in be if ce.get(k)!=be[k]],'missing_prior_node_contexts':missing_contexts,'edge_replays':replays,'node_checks':node_checks,'published_bytes_identical':{p:(OUT/'kgx-current'/p).read_bytes()==(ROOT/'pages/downloads'/p).read_bytes() for p in ('nodes.tsv','edges.tsv')}}
