    for q in edge.get('endpoint_qualifiers',[]):
        role=q['endpoint']; display=element.get('data-'+role); node=nodes[display]
        cells=row.xpath('./td'); cell=cells[0 if role=='subject' else 2]
        qchecks={'native_endpoint':element.get('data-'+role+'-id')==edge[role],'distinct_display':display!=edge[role],'native_node_retained':edge[role] in nodes,'display_base_id':node.get('data-base-node-id')==edge[role],'visible_construct_label':'experimental construct' in node.get('data-node-label',''),'full_description_accessible':q['description'] in node.get('aria-label',''),'correct_table_cell':norm(q['description']) in norm(cell.text_content()),'qualifier_evidence':all(norm(e.get('quote',e.get('source_assertion',''))) in norm(cell.text_content()) for e in q['evidence'])}
        qualifier_checks.append({'edge':edge['id'],'role':role,'checks':qchecks})
edge_endpoints={e[role] for e in record['mechanistic_edges'] for role in ('subject','object')}
declared={*[n['id'] for key in ('participants','reactions') for n in record[key]],*[n['id'] for n in record['taxa'] if n['id'] in edge_endpoints]}
if record['id'] in edge_endpoints: declared.add(record['id'])
report['diagram']={'nodes':len(nodes),'declared_nodes':len(declared),'missing_declared':sorted(declared-set(nodes)),'edges':len(svg_edges),'expected_edges':len(record['mechanistic_edges']),'edge_checks':edge_checks,'qualifier_checks':qualifier_checks,'all_node_links_exist':all(doc.xpath('//*[@id=$id]',id=n.get('href','')[1:]) for n in nodes.values())}
(OUT/'diagram.svg').write_text(raw)
css=(ROOT/'pages/assets/pathway-network.css').read_text()
styled=raw.replace('><title','><style>'+css+'</style><title',1)
(OUT/'diagram-styled.svg').write_text(styled)

fixture=OUT/'policy-fixture';(fixture/'data/pathways').mkdir(parents=True,exist_ok=True);(fixture/'conf').mkdir(exist_ok=True)
shutil.copytree(ROOT/'data/identifier_authorities',fixture/'data/identifier_authorities',dirs_exist_ok=True)
shutil.copyfile(ROOT/'conf/identifier_policy.yaml',fixture/'conf/identifier_policy.yaml')
def policy_case(name,mutate,expected):
    d=copy.deepcopy(record); mutate(d)
    (fixture/'data/pathways/probe.yaml').write_text(yaml.safe_dump(d,sort_keys=False))
    errors=identifier_errors(fixture)
    return {'case':name,'errors':errors,'passed':not errors if expected=='PASS' else any(expected in e for e in errors)}
report['identifier_controls']=[policy_case('unaltered final record',lambda r:None,'PASS'),policy_case('missing native pathway',lambda r:r.update(id='MetaCyc:NONEXISTENT-INDEPENDENT-251-PROBE'),'ID_NOT_FOUND'),policy_case('contextual MetaCyc pathway labels are deliberately permitted',lambda r:r.update(label='deliberately contextual pathway display'),'PASS'),policy_case('contextual CHEBI labels under MetaCyc are deliberately permitted',lambda r:r['participants'][0].update(label='deliberately contextual chemical display'),'PASS'),policy_case('wrong taxon label',lambda r:r['taxa'][0].update(label='intentionally false taxon name'),'LABEL_MISMATCH'),policy_case('contextual Rhea labels under MetaCyc are deliberately permitted',lambda r:r['reactions'][0].update(label='deliberately contextual reaction display'),'PASS'),policy_case('missing chemical ID still rejected',lambda r:r['participants'][0].update(id='CHEBI:999999999'),'ID_NOT_FOUND'),policy_case('missing Rhea ID still rejected',lambda r:r['reactions'][0].update(id='RHEA:999999999'),'ID_NOT_FOUND'),policy_case('wrong MetaCyc protein label still rejected',lambda r:next(x for x in r['participants'] if x['id']=='MetaCyc:G18NG-12642-MONOMER').update(label='intentionally false protein name'),'LABEL_MISMATCH')]
terms={}
for filename in ('sources.json','ontology.json'):terms.update(json.loads((ROOT/'data/identifier_authorities'/filename).read_text())['terms'])
named=[record]+[n for key in ('participants','taxa','reactions') for n in record[key]]
report['canonical_label_comparison']={'scope':'All 31 maintained named IDs directly compared with independently replayed authority labels, irrespective of contextual-label gate exceptions.','count':len(named),'mismatches':[{'id':n['id'],'actual':n['label'],'authority':terms[n['id']]['label']} for n in named if n['label']!=terms[n['id']]['label']]}
qualified_index=next(i for i,e in enumerate(record['mechanistic_edges']) if e.get('endpoint_qualifiers'))
def mutate_qualifier(r):return r['mechanistic_edges'][qualified_index]['endpoint_qualifiers'][0]
def schema_case(name,mutate,expected):
    d=copy.deepcopy(record);mutate(d)
    try: validate_record(d); errors=[]
    except ValidationError as error: errors=list(error.errors)
    return {'case':name,'errors':errors,'passed':bool(errors) if expected=='FAIL' else not errors}
report['schema_controls']=[schema_case('unaltered record',lambda r:None,'PASS'),schema_case('qualification on reaction endpoint',lambda r:mutate_qualifier(r).update(endpoint='object'),'FAIL'),schema_case('duplicate qualifier endpoint role',lambda r:r['mechanistic_edges'][qualified_index]['endpoint_qualifiers'].append(copy.deepcopy(mutate_qualifier(r))),'FAIL'),schema_case('unsupported qualifier kind',lambda r:mutate_qualifier(r).update(kind='invented'),'FAIL'),schema_case('undeclared qualifier reference',lambda r:mutate_qualifier(r)['evidence'][0].update(reference_id='PMID:999999999'),'FAIL'),schema_case('structured assertion missing locator',lambda r:r['mechanistic_edges'][0]['evidence'][0].pop('source_locator'),'FAIL')]
checker=validator(); unknown=copy.deepcopy(record);unknown['reviewer_invented_field']='not allowed'
report['closed_schema_controls']={'unaltered_pass':not checker.validate(record,TARGET_CLASS).results,'unknown_field_rejected':bool(checker.validate(unknown,TARGET_CLASS).results)}
report['passed']=not report['corpus']['changed'] and not report['corpus']['removed'] and report['corpus']['added']==[TARGET] and not report['kgx']['removed_edges'] and not report['kgx']['changed_prior_edges'] and not missing_contexts and all(report['kgx']['published_bytes_identical'].values()) and all(all(r['checks'].values()) for r in replays+node_checks+edge_checks+qualifier_checks) and not report['diagram']['missing_declared'] and len(svg_edges)==len(record['mechanistic_edges']) and report['diagram']['all_node_links_exist'] and all(r['passed'] for r in report['identifier_controls']+report['schema_controls']) and all(report['closed_schema_controls'].values())
report['passed']=report['passed'] and all(report['reference_bindings'].values()) and not report['canonical_label_comparison']['mismatches']
(OUT/'record-integration-audit.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'passed':report['passed'],'corpus':report['corpus'],'new_edges':len(replays),'diagram_nodes':len(nodes),'qualifiers':len(qualifier_checks),'failed_checks':[r for r in replays+edge_checks+qualifier_checks if not all(r['checks'].values())],'control_failures':[r for r in report['identifier_controls']+report['schema_controls'] if not r['passed']]},indent=2))
